<script>
function closeCat(){ document.getElementById('catModal').classList.add('hidden'); document.getElementById('catModal').classList.remove('flex');}
function editCat(id,name,role,days,branch){ document.getElementById('edit_id').value=id; document.getElementById('edit_name').value=name; document.getElementById('edit_role').value=role; document.getElementById('edit_days').value=days; if(document.getElementById('edit_branch')) document.getElementById('edit_branch').value=branch; document.getElementById('editModal').classList.remove('hidden'); document.getElementById('editModal').classList.add('flex');}
function closeEdit(){ document.getElementById('editModal').classList.add('hidden'); document.getElementById('editModal').classList.remove('flex');}
document.getElementById('editForm')?.addEventListener('submit', function(e){ e.preventDefault(); const fd=new FormData(this); fetch(this.action,{method:'POST', headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'}, body:fd}).then(r=>r.json()).then(j=>{ if(j.status==='success') window.location=j.url; else alert(Object.values(j.error||{}).join("\n")); });});
</script>
